-- 1. The bot account. "@bot.lowispike.invalid" now also marks an account as a bot (profiles.bot), next to the old crowd/gate-test addresses.
create or replace function public.lowi_is_bot(uid uuid) returns boolean language sql stable security definer set search_path to '' as $f$select coalesce((select u.email like 'crowd%@crowd.lowispike.invalid' or u.email like 'lowispike.gatetest+%@gmail.com' or u.email like '%@bot.lowispike.invalid' from auth.users u where u.id=uid),false)$f$;
