create table if not exists public.nibblo_menu (slot text not null, idx int not null, rec text not null, emoji text not null, name_en text not null, line_en text not null, photo text not null, head text not null, primary key (slot, idx));
create table if not exists public.nibblo_intro (slot text not null, idx int not null, en text not null, primary key (slot, idx));
create table if not exists public.nibblo_log (id text primary key, posted_at timestamptz not null default now());
alter table public.nibblo_menu enable row level security; alter table public.nibblo_intro enable row level security; alter table public.nibblo_log enable row level security;
revoke all on public.nibblo_menu, public.nibblo_intro, public.nibblo_log from anon, authenticated;
