-- 3. One post: the chat message (id nb-YYYYMMDD-slot) and the same meal in For You (id s + message id), like a member sharing a logged meal.
--    The dish and intro are chosen by (day number since 1 Jan 2026) mod count, the same rule as nibblo-core.js pick().
create or replace function public.nibblo_post(p_day date, p_slot text, p_at timestamptz default now()) returns text language plpgsql security definer set search_path to '' as $f$
declare dn int := p_day - date '2026-01-01'; nm int; ni int; m record; i record; mid text := 'nb-' || to_char(p_day, 'YYYYMMDD') || '-' || p_slot; k int;
begin
  if p_slot not in ('m', 'n', 'e') then return null; end if;
  insert into public.nibblo_log (id, posted_at) values (mid, p_at) on conflict (id) do nothing;
  get diagnostics k = row_count; if k = 0 then return null; end if;
  select count(*) into nm from public.nibblo_menu where slot = p_slot; select count(*) into ni from public.nibblo_intro where slot = p_slot;
  if nm = 0 or ni = 0 then raise exception 'nibblo: empty menu for %', p_slot; end if;
  select * into m from public.nibblo_menu where slot = p_slot and idx = ((dn % nm) + nm) % nm;
  select * into i from public.nibblo_intro where slot = p_slot and idx = ((dn % ni) + ni) % ni;
  insert into public.messages (id, room, user_id, who, body, created_at) values (mid, 'all', '59bb3615-b344-4c45-ab0f-0a5de5cd8df3'::uuid, 'Nibblo', m.head || ' ' || i.en || ' ' || m.line_en, p_at) on conflict (id) do nothing;
  insert into public.posts (id, user_id, who, cap, photo_url, rec, lv, meta, created_at) values ('s' || mid, '59bb3615-b344-4c45-ab0f-0a5de5cd8df3'::uuid, 'Nibblo', i.en || ' ' || m.emoji || ' ' || m.name_en || '. ' || m.line_en, m.photo, m.rec, 2,
    jsonb_build_object('dish', m.name_en, 'from', 'community', 'spike', 'low', 'nb', jsonb_build_object('d', to_char(p_day, 'YYYYMMDD'), 's', p_slot)), p_at) on conflict (id) do nothing;
  return mid;
end $f$;

-- 4. The clock: every 5 minutes; a slot posts from its Berlin time for 120 minutes, once. Berlin time, so summer/winter time needs nothing.
create or replace function public.nibblo_tick(p_now timestamptz default now()) returns text language plpgsql security definer set search_path to '' as $f$
declare l timestamp := p_now at time zone 'Europe/Berlin'; t time := l::time; s text;
begin
  s := case when t >= time '07:30' and t < time '07:30' + interval '120 minutes' then 'm' when t >= time '12:30' and t < time '12:30' + interval '120 minutes' then 'n' when t >= time '18:30' and t < time '18:30' + interval '120 minutes' then 'e' end;
  if s is null then return null; end if;
  return public.nibblo_post(l::date, s, p_now);
end $f$;
revoke execute on function public.nibblo_post(date, text, timestamptz), public.nibblo_tick(timestamptz) from public, anon, authenticated;
select cron.unschedule(jobid) from cron.job where jobname = 'nibblo-meals';
select cron.schedule('nibblo-meals', '*/5 * * * *', 'select public.nibblo_tick()');
commit;
